func TestRoles(t *testing.T) {
	for _, c := range []struct {
		route string
		role  string
		req   apiCase
	}{
		{"quote_booking", "guest", quoteBookingBaseline},
		{"create_booking", "guest", createBookingBaseline},
		{"confirm_booking", "guest", confirmBookingBaseline},
		{"cancel_booking", "guest", cancelBookingBaseline},
		{"check_in", "staff", checkInBaseline},
		{"check_out", "staff", checkOutBaseline},
		{"mark_no_show", "staff", markNoShowBaseline},
	} {
		t.Run(c.route, func(t *testing.T) {
			svc := &fakeService{}
			wantProblem(t, do(svc, "", c.req), http.StatusUnauthorized)
			wantProblem(t, do(svc, "nobody", c.req), http.StatusForbidden)
			if len(svc.calls) != 0 {
				t.Fatalf("the service was called without the role: %v", svc.calls)
			}
			if rec := do(svc, c.role, c.req); rec.Code >= 400 {
				t.Fatalf("the route's own role was refused: %d %s", rec.Code, rec.Body)
			}
		})
	}
}

// TestRouteTable: the table lists every route once, in the mux's own terms.
func TestRouteTable(t *testing.T) {
	if len(Routes) != 7 {
		t.Fatalf("%d routes, want 7", len(Routes))
	}
	if r := Routes[0]; r.Name != "quote_booking" || r.Method != "POST" || r.Path != "/api/v1/quotes" || r.Role != "guest" || r.Call != "quote" || r.Status != 200 {
		t.Errorf("Routes[0] = %+v", r)
	}
	if r := Routes[1]; r.Name != "create_booking" || r.Method != "POST" || r.Path != "/api/v1/bookings" || r.Role != "guest" || r.Call != "new_booking" || r.Status != 201 {
		t.Errorf("Routes[1] = %+v", r)
	}
	if r := Routes[2]; r.Name != "confirm_booking" || r.Method != "POST" || r.Path != "/api/v1/bookings/{id}/confirm" || r.Role != "guest" || r.Call != "Booking.confirm" || r.Status != 200 {
		t.Errorf("Routes[2] = %+v", r)
	}
	if r := Routes[3]; r.Name != "cancel_booking" || r.Method != "POST" || r.Path != "/api/v1/bookings/{id}/cancel" || r.Role != "guest" || r.Call != "Booking.cancel" || r.Status != 200 {
		t.Errorf("Routes[3] = %+v", r)
	}
	if r := Routes[4]; r.Name != "check_in" || r.Method != "POST" || r.Path != "/api/v1/bookings/{id}/check-in" || r.Role != "staff" || r.Call != "Booking.check_in" || r.Status != 200 {
		t.Errorf("Routes[4] = %+v", r)
	}
	if r := Routes[5]; r.Name != "check_out" || r.Method != "POST" || r.Path != "/api/v1/bookings/{id}/check-out" || r.Role != "staff" || r.Call != "Booking.check_out" || r.Status != 200 {
		t.Errorf("Routes[5] = %+v", r)
	}
	if r := Routes[6]; r.Name != "mark_no_show" || r.Method != "POST" || r.Path != "/api/v1/bookings/{id}/no-show" || r.Role != "staff" || r.Call != "Booking.mark_no_show" || r.Status != 204 {
		t.Errorf("Routes[6] = %+v", r)
	}
}

